  {"a": "2002", "e": "The euro already existed in bank accounts three years earlier.", "p": "In which year did euro notes and coins first reach people's pockets?", "s": "Coins and banknotes", "w": ["1996", "1999", "2005"]},
  {"a": "Silver", "p": "One British pound once equalled a pound in weight of which metal?", "s": "Coins and banknotes", "w": ["Copper", "Bronze", "Nickel"]},
  {"a": "A bench", "e": "Money changers sat at a bench in the market square.", "p": "The word bank comes from an Italian word for which piece of furniture?", "s": "Coins and banknotes", "w": ["A chest", "A table", "A stool"]},
  {"a": "Goldsmiths", "p": "Whose receipts for stored gold became some of England's first banknotes?", "s": "Coins and banknotes", "w": ["Innkeepers", "Shipowners", "Bookbinders"]},
