  {"a": "Holy water", "e": "He wrote about this early vending machine almost 2,000 years ago.", "p": "Hero of Alexandria described a coin-operated machine that gave out what?", "s": "Coins and banknotes", "w": ["Olive oil", "Fresh milk", "Warm bread"]},
  {"a": "The 1960s", "e": "A bank in north London opened one in 1967.", "p": "In which decade did the first cash machine start handing out money?", "s": "Banks and saving", "w": ["The 1940s", "The 1950s", "The 1970s"]},
  {"a": "Meals in restaurants", "p": "The Diners Club card of 1950 was first used to pay for what?", "s": "Banks and saving", "w": ["Rooms in hotels", "Seats on trains", "Nights at inns"]},
