  {"a": "A saloon", "e": "James Ritty built it in 1879 to keep track of his takings.", "p": "What kind of business did the man who invented the cash register run?", "s": "Shops and markets", "w": ["A bakery", "A grocery", "A pharmacy"]},
  {"a": "A hammer and chisel", "e": "The can opener arrived about fifty years after the can.", "p": "Early tin cans told the buyer to open them with which pair of tools?", "s": "Shops and markets", "w": ["A knife and fork", "A key and string", "A screw and pliers"]},
  {"a": "A tall cone", "e": "Shoppers broke pieces off the sugar loaf with iron nippers.", "p": "Before loose sugar, shops sold sugar in what shape?", "s": "Shops and markets", "w": ["A flat brick", "A round ring", "A thick rope"]},
