  {"a": "Two boards", "e": "He wore one board in front and one behind.", "p": "What did a Victorian sandwich man carry through the street to advertise a shop?", "s": "Catalogues and advertising", "w": ["A large bell", "A paper lantern", "A painted flag"]},
  {"a": "New apartments", "e": "A New York station sold the airtime to a housing company.", "p": "The first American radio advertisement in 1922 was selling what?", "s": "Catalogues and advertising", "w": ["Motor cars", "Bars of soap", "Tins of coffee"]},
  {"a": "A watch", "e": "It lasted about ten seconds and showed a clock face.", "p": "What did the first American television advertisement in 1941 sell?", "s": "Catalogues and advertising", "w": ["A razor", "A radio", "A camera"]},
  {"a": "Paris", "e": "Georges Claude's neon tube lit a barber's shop there in 1912.", "p": "Where did the first bright neon advertising signs appear in the 1910s?", "s": "Catalogues and advertising", "w": ["London", "Berlin", "Vienna"]},
